regions.formulas:
function enhRate(n){
  return Math.max(0.5,99*Math.pow(0.99,n)); // % 반환, 최소 0.5% 보장
}
const _MALICE_COST_MUL=0.5; // 악의 소비 50% 할인
function _malCost(v){
  const _n=Number(v)||0;
  if(_n<=0)return 0;
  return Math.max(1,Math.ceil(_n*_MALICE_COST_MUL));
}
function enhCostRaw(n){
  return Math.max(20000,Math.ceil((20000+n*3500)*1.5)); // 최소 2만(=1만악의), 0강=3만, 100강=55.5만, 1000강=528만
}
function enhCost(enh,rarity){
  const rMul=[0.5,0.7,1.0,1.3,1.8][_itemEconomyRarity(rarity)];
  return{rate:enhRate(enh)/100,cost:_malCost(Math.ceil(enhCostRaw(enh)*rMul))};
}

regions.ai:
function aiEnhance(item,targetEnh,budget){
  if(!item)return{ok:false,msg:'아이템 없음'};
  const startEnh=item.enh||0;
  if(startEnh>=targetEnh)return{ok:false,msg:'이미 목표 달성'};
  if(budget<=0||G.mats<budget)return{ok:false,msg:'악의 부족'};
  let used=0,tries=0,n=startEnh;
  while(n<targetEnh&&used<budget){
    const{rate,cost}=enhCost(n,item.rarity||0);
    if(used+cost>budget)break;
    used+=cost;tries++;
    if(Math.random()<rate)n++;
  }
  G.mats-=used;
  item.enh=n;
  return{ok:n>=targetEnh,from:startEnh,to:n,target:targetEnh,used,tries};
}

