regions.sanitize:
function _sanitizeCoreState(){
  if(!P||!G)return;
  const _toInt=(v,d=0)=>{const n=Number(v);return Number.isFinite(n)?Math.floor(n):d};
  P.sp=Math.max(0,_toInt(P.sp,0));
  P.ap=Math.max(0,_toInt(P.ap,0));
  G.mats=Math.max(0,_toInt(G.mats,0));
  if(P.skills&&typeof P.skills==='object'){
    for(const k in P.skills){
      const lv=Math.max(0,_toInt(P.skills[k],0));
      P.skills[k]=lv;
    }
  }
  _ensureBaseWingStrike(P);
  if(P._fused&&typeof P._fused==='object'){
    // 합체 구성 스킬 존재 보장만 (min-level 강제 제거 — 하위 합체가 상위 스킬을 끌어내리는 버그 방지)
    for(const fk of Object.keys(P._fused)){
      if(!P._fused[fk]){delete P._fused[fk];continue}
      const _hasFG=typeof _FUSE_GEM_GROUPS!=='undefined'&&_FUSE_GEM_GROUPS&&_FUSE_GEM_GROUPS[fk];
      const fg=_hasFG?_FUSE_GEM_GROUPS[fk]:null;
      const _pairs=(typeof _FUSE_PAIRS!=='undefined'&&_FUSE_PAIRS)?_FUSE_PAIRS:{};
      const ids=(fg&&fg.skills&&fg.skills.length)?fg.skills:(_pairs[fk]||[]);
      if(!ids.length){delete P._fused[fk];continue}
      // 스킬 존재 보장 (레벨 0이면 1로) — min 강제 안 함
      for(const id of ids){
        const lv=Math.max(1,_toInt((P.skills&&P.skills[id])||1,1));
        P.skills[id]=lv;
      }
    }
  }
}

