  P.baseAtk=pd.baseAtk||8; P.baseDef=pd.baseDef||2;
  P.mpR=pd.mpR||0; P.stR=pd.stR||.28;
  P.hp=pd.hp||P.mhp; P.mhp=pd.mhp||350;
  P.mp=pd.mp||P.mmp; P.mmp=pd.mmp||80;
  P.st=pd.st||P.mst; P.mst=pd.mst||100;
  P.speed=pd.speed||2.6;
  P.shield=pd.shield||0;P.mshield=pd.mshield||0;
  P.rage=0; // 분노게이지 (패링 성공 시 적립, 지옥강타 1 소비)
  P.maskOn=pd.maskOn!==undefined?pd.maskOn:true;
  _applyMaskAtlas();
  // Inventory
  if(d.inv){
    INV.bag=d.inv.bag||[];
    INV.equipped=d.inv.equipped||{weapon:null,shield:null,boots:null,armor:null,helmet:null,bow:null,gloves:null,pants:null,belt:null,necklace:null,ring1:null,ring2:null,cape:null,bracelet:null,headband:null,ossuary:null,headband2:null};
    // 슬롯 마이그레이션 (기존 세이브)
    if(INV.equipped.belt===undefined)INV.equipped.belt=null;
    if(INV.equipped.bracelet===undefined)INV.equipped.bracelet=null;
    if(INV.equipped.ossuary===undefined)INV.equipped.ossuary=null; // 유골함 슬롯 (2026-09-01 신규) — 구세이브 기본 미장착
    // 유골 도감 (2026-09-01 도감 개편) — 구세이브 = 빈 도감으로 로드
