  }
  STORAGE={};STORAGE._synced=false;_getStore();
  // 안전장치: 200개 초과 시 잘라냄
  if(STORAGE[0]&&STORAGE[0].length>STORAGE_MAX){STORAGE[0].length=STORAGE_MAX;_persistSharedStorage()}
  // 결정 주머니 복원 + 마이그레이션
  CRYSTAL_BAG=d.crystalBag||[];CRYSTAL_DUST=d.crystalDust||0;
  const _migrateCr=cr=>{if(cr&&_CR_LEGACY_IDS[cr.id])cr.id=_CR_LEGACY_IDS[cr.id]};
  CRYSTAL_BAG.forEach(_migrateCr);
  const _fixCr=it=>{if(!it)return;if(it.socketCount===undefined){const _r=Math.random();it.socketCount=_r<.5?1:_r<.8?2:_r<.95?3:4;it.crystals=new Array(it.socketCount).fill(null)}if(Array.isArray(it.crystals))it.crystals.forEach(_migrateCr)};
  if(INV.bag)INV.bag.forEach(_fixCr);for(const s of SLOT_NAMES)_fixCr(INV.equipped[s]);
  if(STORAGE)for(const k in STORAGE){const st=STORAGE[k];if(Array.isArray(st))st.forEach(_fixCr)}
  // Upgrades
