  // 회전기폭 계열 합체 상태면 LMB 자동 회전참 전환
  if(P._fused&&(P._fused.whirlDet||P._fused.slamStorm||P._fused.stormBeam)&&P.skills.whirlwind>=1)P.activeLMBSk='whirlwind';
  // 구세이브 마이그레이션: dimHalf 제거 (galeSlash 삭제됨)
  if(P._fused.dimHalf)delete P._fused.dimHalf;
  if(P.skills.galeSlash){delete P.skills.galeSlash;}
  if(P.activeChargeSk==='galeSlash')P.activeChargeSk='charge';
  // elemFuse 있는데 sixFuse 없으면 둘 다 세팅
  if(P._fused.elemFuse&&!P._fused.sixFuse)P._fused.sixFuse=true;
  // slamStorm 있는데 whirlDet 없으면 둘 다 세팅
  if(P._fused.slamStorm&&!P._fused.whirlDet)P._fused.whirlDet=true;
  // stormBurst 있으면 stormBeam+하위 전부 보장
  if(P._fused.stormBurst){if(!P._fused.stormBeam)P._fused.stormBeam=true;if(!P.skills.burstLoop)P.skills.burstLoop=1;}
  // stormBeam 있으면 slamStorm+elemFuse+하위 전부 보장
  if(P._fused.stormBeam){if(!P._fused.slamStorm)P._fused.slamStorm=true;if(!P._fused.whirlDet)P._fused.whirlDet=true;if(!P._fused.elemFuse)P._fused.elemFuse=true;if(!P._fused.sixFuse)P._fused.sixFuse=true;if(!P.skills.whirlwind)P.skills.whirlwind=1;if(!P.skills.detonate)P.skills.detonate=1;if(!P.skills.giantSlam)P.skills.giantSlam=1;if(!P.skills.fanShot)P.skills.fanShot=1;if(!P.skills.omniBeam)P.skills.omniBeam=1;if(!P.skills.elemMissile)P.skills.elemMissile=1;if(!P.skills.peaceShield)P.skills.peaceShield=1;if(!P.skills.hellRay)P.skills.hellRay=1;}

  // Lv300 히든: 푸른비 자동 해금
  if(P.lv>=300&&!P.skills.blueShot)P.skills.blueShot=1;
  // Lv700 히든: 버스트루프 자동 해금 (좌클릭)
  if(P.lv>=700&&!P.skills.burstLoop)P.skills.burstLoop=1;
  // elecRepent 있으면 boneStorm 하위 보장
  if(P._fused.elecRepent){if(!P._fused.boneStorm)P._fused.boneStorm=true;if(!P.skills.boneWall)P.skills.boneWall=1;if(!P.skills.hellRay)P.skills.hellRay=1}
  // holyIce 있으면 holyFuse 하위 보장
  if(P._fused.holyIce){if(!P._fused.holyFuse)P._fused.holyFuse=true;if(!P.skills.iceStorm)P.skills.iceStorm=1}
  // 신성빙결→약화영역 체인 보장
  if(P._fused.holyWeak1){if(!P._fused.holyIce)P._fused.holyIce=true;if(!P.skills.weakPhys)P.skills.weakPhys=1}
  if(P._fused.holyWeak2){if(!P._fused.holyWeak1)P._fused.holyWeak1=true;if(!P.skills.weakMag)P.skills.weakMag=1}
  if(P._fused.holyWeak3){if(!P._fused.holyWeak2)P._fused.holyWeak2=true;if(!P.skills.weakPj)P.skills.weakPj=1}
  if(P._fused.holyWeak4){if(!P._fused.holyWeak3)P._fused.holyWeak3=true;if(!P.skills.weakRev)P.skills.weakRev=1}
  // 구버전 마이그레이션 (제거된 키 정리)
  delete P._fused.holyFlame;delete P._fused.holyRevive;delete P._fused.holyApex;
  delete P._fused.weakFuse2;delete P._fused.weakFuse3;delete P._fused.weakFuse4;
  // dimBlast/dimRush/dimThunder/dimSlam 체인 보장
  if(P._fused.dimBlast&&!P._fused.dimRush)P._fused.dimRush=true;
  if(P._fused.dimRush&&!P._fused.dimThunder)P._fused.dimThunder=true;
  if(P._fused.dimThunder&&!P._fused.dimSlam)P._fused.dimSlam=true;
  if(P._fused.dimSlam&&!P._fused.dimBreach)P._fused.dimBreach=true;
  // 합체 구성 스킬 습득 보장: 합체 상태인데 레벨 0인 스킬 자동 보정
  for(const[_fk,_fv]of Object.entries(_FUSE_PAIRS||{})){
    if(P._fused&&P._fused[_fk]){for(const _sid of _fv){if(!P.skills[_sid])P.skills[_sid]=1}}
  }
  // min-level 강제 전면 제거 — 하위 합체가 상위 스킬을 끌어내리는 버그 방지
  // 합체 레벨 동기화는 스킬 패널(_skClick)에서만 처리
  // 스킬 슬롯 복원
  if(d.activeChargeSk)P.activeChargeSk=d.activeChargeSk;
  // 진동보행 삭제됨 — 마이그레이션
  if(P.activeChargeSk==='quakeStride')P.activeChargeSk='charge';
  // 유효성: 세팅된 스킬이 미습득이면 기본 돌진으로
  if(P.activeChargeSk!=='charge'&&!(P.skills[P.activeChargeSk]>=1))P.activeChargeSk='charge';
  // 활 스킬 슬롯 복원 (T자동)
  if(d.activeBowSk)P.activeBowSk=d.activeBowSk;
  if(!P.activeBowSk)P.activeBowSk='normal';
  if(P.activeBowSk==='maliceMortar'||P.activeBowSk==='ghostXbowTurret')P.activeBowSk='normal'; // 마이그레이션
  if(P.activeBowSk!=='normal'&&!(P.skills[P.activeBowSk]>=1))P.activeBowSk='normal';
  if(P.activeBowSk==='fanShot'&&(_isFused('sixFuse')||_isFused('elemFuse')||_isFused('stormBeam')))P.activeBowSk='normal';
  // 기본 스킬 습득 마이그레이션
  if(!P.skills.spikeTrap)P.skills.spikeTrap=1;
  if(!P.skills.holyDome){P.skills.holyDome=1}
  if(!P.skills.giantSlam){P.skills.giantSlam=1}
  // holyDome/giantSlam 슬롯 강제 고정은 슬롯 복원 후 실행 (아래)
  // 기술 스킬 슬롯 복원 (Space)
  if(d.activeTechSk)P.activeTechSk=d.activeTechSk;
  if(!P.activeTechSk||P.activeTechSk==='spikeTrap')P.activeTechSk='giantSlam';
  if(P.activeTechSk!=='giantSlam'&&!(P.skills[P.activeTechSk]>=1))P.activeTechSk='giantSlam';
  // 마법 스킬 슬롯 복원 (스킬 소유 OR 슬롯 등록 스킬이면 유효)
  if(d.activeMagicSk)P.activeMagicSk=d.activeMagicSk;
  if(!P.activeMagicSk||P.activeMagicSk==='fanShot')P.activeMagicSk='fireball';
  {const _msDef=typeof SKILL_SLOT_DEFS!=='undefined'&&SKILL_SLOT_DEFS.magic;
  const _msValid=P.activeMagicSk==='fireball'||(P.skills[P.activeMagicSk]>=1)||(_msDef&&_msDef.skills.includes(P.activeMagicSk));
  if(!_msValid)P.activeMagicSk='fireball'}
  // LMB/RMB/Q 슬롯 복원
  if(d.activeLMBSk)P.activeLMBSk=d.activeLMBSk;
  if(!P.activeLMBSk)P.activeLMBSk='whirlwind';
  // 회전기폭 계열 합체 시 LMB 강제 회전참 (세이브 값 덮어쓰기 후 재적용)
  if(P._fused&&(P._fused.whirlDet||P._fused.slamStorm||P._fused.stormBeam)&&P.skills.whirlwind>=1)P.activeLMBSk='whirlwind';
  if(d.activeRMBSk)P.activeRMBSk=d.activeRMBSk;
  if(!P.activeRMBSk)P.activeRMBSk='shieldBlock';
  if(d.activeQSk)P.activeQSk=d.activeQSk;
  if(!P.activeQSk||P.activeQSk==='iceOrb')P.activeQSk='parry'; // 얼음보주→선택스킬 마이그레이션
  if(d.activeCtSk)P.activeCtSk=d.activeCtSk;
  if(!P.activeCtSk)P.activeCtSk='ghostWalk';
  {const _ctDef=typeof SKILL_SLOT_DEFS!=='undefined'&&SKILL_SLOT_DEFS.ct;
  const _ctValid=P.activeCtSk==='ghostWalk'||(P.skills[P.activeCtSk]>=1)||(_ctDef&&_ctDef.skills.includes(P.activeCtSk));
  if(!_ctValid)P.activeCtSk='ghostWalk'}
  // 합체 흡수 스킬 → 호스트 자동 전환 (세이브 로드 시)
  if(P.activeCtSk==='ghostWalk'&&P._fused&&P._fused.timeStep&&P.skills.timeWarp>=1)P.activeCtSk='timeWarp';
  // 로드 후 흡수 스킬 활성슬롯 동기화
  _syncActiveSkAfterReset(_getAllAbsorbed());
  // 숫자 스킬 슬롯 복원
  if(d.skillSlots&&Array.isArray(d.skillSlots)){
    for(let _si=0;_si<6;_si++){SKILL_SLOTS[_si]=d.skillSlots[_si]||null}
  }
  if(d.ultSlot)ULT_SLOT=d.ultSlot;
  // 시작/구세이브 선택 슬롯은 아래 공용 계약 복구로 정규화
  // chainStun→chainAssault 세이브 마이그레이션
  if(P.skills.chainStun&&!P.skills.chainAssault){P.skills.chainAssault=P.skills.chainStun;delete P.skills.chainStun}
  if(P._skProf&&P._skProf.chainStun){P._skProf.chainAssault=P._skProf.chainStun;delete P._skProf.chainStun}
  // chainAssault ↔ chainSlam 양방향 자동 보장
  if(P.skills.chainAssault>=1&&!P.skills.chainSlam)P.skills.chainSlam=1;
  if(P.skills.chainSlam>=1&&!P.skills.chainAssault)P.skills.chainAssault=1;
  // 미습득 스킬 슬롯 정리 + 합체 흡수 스킬 슬롯 자동 제거
  const _fKick=_getAllAbsorbed();
  for(let _si=0;_si<6;_si++){if(SKILL_SLOTS[_si]&&(!(P.skills[SKILL_SLOTS[_si]]>=1)||_fKick.includes(SKILL_SLOTS[_si])))SKILL_SLOTS[_si]=null}
  if(ULT_SLOT&&!(P.skills[ULT_SLOT]>=1))ULT_SLOT=null;
  // 고정슬롯 전용 스킬은 선택슬롯에서 제거 (마이그레이션)
  // SKILL_SLOTS[4] = Space 분노 폭발 전용 슬롯
  const _fixedKick=['bladeShot','fanShot','omniBeam','bladeDash','ghostWalk','iceOrb','timeWarp'];
  for(let _si=0;_si<6;_si++){if(_fixedKick.includes(SKILL_SLOTS[_si]))SKILL_SLOTS[_si]=null}
  // 배운 액티브 스킬이 슬롯에 없으면 자동 배정 (합체 흡수/고정슬롯 제외)
  const _fixedSlotSk=['bladeShot','fanShot','omniBeam','bladeDash','shieldThrow','blastShot','ghostWalk','iceOrb','timeWarp','chainSlam','chainAssault','chainSlash','needleShot','peaceShield','hellRay','blueShot','burstLoop','holyDome','fireball','arcLaser','ltnChaser']; // 고정스킬 (슬롯 자동배정 제외)
  _repairAreaSkillSlot(); // 구버전 슬롯을 일반=1~4, 분노 폭발=Space, 영역=F 계약으로 복구
  const _actIds=SKILL_LIST.filter(sk=>sk.act&&!sk.ult&&P.skills[sk.id]>=1&&!_fKick.includes(sk.id)&&!_fixedSlotSk.includes(sk.id)).map(sk=>sk.id);
  _actIds.forEach(id=>{
    if(!SKILL_SLOTS.includes(id)){const _ei=_findAutoSkillSlot(id);if(_ei>=0)SKILL_SLOTS[_ei]=id}
  });
  _sanitizeCoreState();
  return true;
}

regions.xp:
function _restoreExpProgress(pd){
  const maxExp=pd.maxExp||15;
  if((pd.lv||1)<1000||(Number.isFinite(maxExp)&&maxExp>0))return{exp:pd.exp||0,maxExp};
  // 구버전 초월 필요 경험치의 32비트 오버플로 값만 복구한다.
  return{exp:Math.max(0,Number(pd.exp)||0),maxExp:_calcMaxExp(pd.lv)};
}

regions.auto:
function doAutoSave(){
  const now=Date.now();
  if(now-_lastSaveTime<10000)return;
  if(G.on&&_dbReady)dbSave();
}

saves:
async function dbSave(){
  if(window._parryLesson?.active)return;
  if(!_charId||!_dbReady||_saving)return;
  if(!P)return;
  _saving=true;
  _sanitizeCoreState();
  // 계정 공유: 악의와 창고는 localStorage에 저장
  try{_saveSharedMats(G.mats||0);_flushSharedStorage()}catch(e){}
  try{
    const saveData={
      player:{
        lv:P.lv, exp:P.exp, maxExp:P.maxExp, sp:P.sp, ap:P.ap||0, passiveQueue:_passiveQueueItems(),
        transLvDate:P._transLvDate||null, transLvCount:P._transLvCount||0, apBossCleared:P._apBossCleared||[], goddessGift:P._goddessGift||[], _lvStatMigrated:P._lvStatMigrated||false,
        baseAtk:P.baseAtk, baseDef:P.baseDef, mpR:P.mpR, stR:P.stR,
        hp:P.hp, mhp:P.mhp, mp:P.mp, mmp:P.mmp, st:P.st, mst:P.mst, speed:P.speed,
        shield:P.shield, mshield:P.mshield, maskOn:P.maskOn
      },
      inv:{bag:INV.bag,equipped:INV.equipped,ossCollect:INV.ossCollect||{}},
      stats:{...STATS},
      passives:{...PASSIVES},grit:_grit,gritCostModeV2:1,
      qslots:QSLOTS,
      game:{stage:G.stage,kills:G.kills,mats:0,irisSz:G._irisSz||20,taRecords:G._taRecords||{},clearRecords:G._clearRecords||{},comboMax:G.comboMax||0,playTime:G.playTime||0,cutsceneDone:G._cutsceneDone||false},
      bagMax:BAG_MAX,
      hellCleared:G.hellCleared||[],
      storage:{}, /* 창고는 localStorage 공유 */
      crystalBag:CRYSTAL_BAG,crystalDust:CRYSTAL_DUST,
      upgrades:{...UPGRADES},
      potLv:{...POT_LV},
      skills:{...P.skills},
      fused:P._fused||{},skProf:P._skProf||{},fuseProfSec:P._fuseProfSec||{},cardProf:P._cardProf||{},catProf:P._catProf||{},
      activeChargeSk:P.activeChargeSk||'charge',
      activeBowSk:P.activeBowSk||'normal',
      activeTechSk:P.activeTechSk||'giantSlam',
      activeMagicSk:P.activeMagicSk||'fireball',
      activeLMBSk:P.activeLMBSk||'whirlwind',
      activeRMBSk:P.activeRMBSk||'shieldBlock',
      activeQSk:P.activeQSk||'parry',
      activeCtSk:P.activeCtSk||'ghostWalk',
      skillSlots:SKILL_SLOTS,
      ultSlot:ULT_SLOT,
      charIdx:_charIdx
    };
    const{data:updated,error}=await sb.from('characters').update({
      data:saveData,
      updated_at:new Date().toISOString()
    }).eq('id',_charId).select('id');
    if(error){if(!IS_ELECTRON)console.error('[DB] Save error:',error.message)}
    else if(updated&&updated.length===1&&updated[0].id===_charId)_lastSaveTime=Date.now();
    else if(!IS_ELECTRON)console.error('[DB] Save failed: character missing or update denied');
  }catch(e){if(!IS_ELECTRON)console.error('[DB] Save exception:',e)}
  _saving=false;if(_pendingForce){_pendingForce=false;if(Date.now()-_lastSaveTime>=5000)dbSave()}
}

