regions.sanitize:
function _sanitizeCoreState(){
  if(!P||!G)return;
  const _toInt=(v,d=0)=>{const n=Number(v);return Number.isFinite(n)?Math.floor(n):d};
  P.sp=Math.max(0,_toInt(P.sp,0));
  P.ap=Math.max(0,_toInt(P.ap,0));
  G.mats=Math.max(0,_toInt(G.mats,0));
  if(P.skills&&typeof P.skills==='object'){
    for(const k in P.skills){
      const lv=Math.max(0,_toInt(P.skills[k],0));
      P.skills[k]=lv;
    }
  }
  _ensureBaseWingStrike(P);
  if(P._fused&&typeof P._fused==='object'){
    // 합체 구성 스킬 존재 보장만 (min-level 강제 제거 — 하위 합체가 상위 스킬을 끌어내리는 버그 방지)
    for(const fk of Object.keys(P._fused)){
      if(!P._fused[fk]){delete P._fused[fk];continue}
      const _hasFG=typeof _FUSE_GEM_GROUPS!=='undefined'&&_FUSE_GEM_GROUPS&&_FUSE_GEM_GROUPS[fk];
      const fg=_hasFG?_FUSE_GEM_GROUPS[fk]:null;
      const _pairs=(typeof _FUSE_PAIRS!=='undefined'&&_FUSE_PAIRS)?_FUSE_PAIRS:{};
      const ids=(fg&&fg.skills&&fg.skills.length)?fg.skills:(_pairs[fk]||[]);
      if(!ids.length){delete P._fused[fk];continue}
      // 스킬 존재 보장 (레벨 0이면 1로) — min 강제 안 함
      for(const id of ids){
        const lv=Math.max(1,_toInt((P.skills&&P.skills[id])||1,1));
        P.skills[id]=lv;
      }
    }
  }
}

regions.restore:
function dbRestore(d){
  if(!d)return false;
  // 생성 직후에는 player 없이 charIdx만 저장된다. 이전 캐릭터 캐시보다 슬롯이 우선이다.
  const savedCharIdx=Number.isInteger(d.charIdx)&&d.charIdx>=0&&d.charIdx<CHAR_LIST.length?d.charIdx:0;
  if(savedCharIdx!==_charIdx)_loadCharAtlas(savedCharIdx);
  if(!d.player)return false;
  // Player
  const pd=d.player;
  P.lv=pd.lv||1; const _xpRestore=_restoreExpProgress(pd); P.exp=_xpRestore.exp; P.maxExp=_xpRestore.maxExp;
  P._transLvDate=pd.transLvDate||null; P._transLvCount=pd.transLvCount||0; P._apBossCleared=pd.apBossCleared||[]; P._goddessGift=pd.goddessGift||[];
  // SP/AP: 저장된 값 그대로 복원 (재계산 폐지 — 보스+10SP 등 보너스 누락, 합체 비용 오산 등 버그 다수)
  P.sp=pd.sp||0;
  P.ap=pd.ap||0;
  P.baseAtk=pd.baseAtk||8; P.baseDef=pd.baseDef||2;
  P.mpR=pd.mpR||0; P.stR=pd.stR||.28;
  P.hp=pd.hp||P.mhp; P.mhp=pd.mhp||350;
  P.mp=pd.mp||P.mmp; P.mmp=pd.mmp||80;
  P.st=pd.st||P.mst; P.mst=pd.mst||100;
  P.speed=pd.speed||2.6;
  P.shield=pd.shield||0;P.mshield=pd.mshield||0;
  P.rage=0; // 분노게이지 (패링 성공 시 적립, 지옥강타 1 소비)
  P.maskOn=pd.maskOn!==undefined?pd.maskOn:true;
  _applyMaskAtlas();
  // Inventory
  if(d.inv){
    INV.bag=d.inv.bag||[];
    INV.equipped=d.inv.equipped||{weapon:null,shield:null,boots:null,armor:null,helmet:null,bow:null,gloves:null,pants:null,belt:null,necklace:null,ring1:null,ring2:null,cape:null,bracelet:null,headband:null,ossuary:null};
    // 슬롯 마이그레이션 (기존 세이브)
    if(INV.equipped.belt===undefined)INV.equipped.belt=null;
    if(INV.equipped.bracelet===undefined)INV.equipped.bracelet=null;
    if(INV.equipped.ossuary===undefined)INV.equipped.ossuary=null; // 유골함 슬롯 (2026-09-01 신규) — 구세이브 기본 미장착
    // 유골 도감 (2026-09-01 도감 개편) — 구세이브 = 빈 도감으로 로드
    INV.ossCollect=(d.inv.ossCollect&&typeof d.inv.ossCollect==='object')?d.inv.ossCollect:{};
    // 팔찌 brType 마이그레이션: 기존 팔찌는 악마의 팔찌로
    const _fixBr=(it)=>{if(it&&it.slot==='bracelet'&&!it.brType)it.brType='demon'};
    INV.bag.forEach(_fixBr);_fixBr(INV.equipped.bracelet);
    if(STORAGE&&STORAGE.items)STORAGE.items.forEach(_fixBr);
    if(INV.equipped.headband===undefined)INV.equipped.headband=null;
    // 팔찌/귀걸이 ??? 아이템 수리 마이그레이션
    const _fixBrHb=(it)=>{if(it&&it.name==='???'){const _n={bracelet:{0:['낡은 팔찌','은 팔찌','흑요석 팔찌','미스릴 팔찌','천벌의 팔찌']},headband:{0:['낡은 귀걸이','은사 귀걸이','흑요석 귀걸이','미스릴 귀걸이','천벌의 귀걸이']}};if(_n[it.slot]){it.name=(_n[it.slot][it.el||0]||_n[it.slot][0])[Math.min(it.tier||0,4)];it.emoji=SLOT_EMOJI[SLOT_NAMES.indexOf(it.slot)];if(!it.def&&it.slot==='bracelet'){it.def=1+(it.tier||0);it.eDef=1+(it.tier||0);it.bonusHp=5+(it.tier||0)*5}if(!it.eDef&&it.slot==='headband'){it.eDef=2+(it.tier||0)*2;it.mpRegen=1+(it.tier||0)}}}};
    INV.bag.forEach(_fixBrHb);_fixBrHb(INV.equipped.bracelet);_fixBrHb(INV.equipped.headband);
    // 방패→견갑 이름 마이그레이션
    const _fixShieldName=(it)=>{if(it&&it.name&&it.slot==='shield')it.name=it.name.replace(/방패/g,'견갑').replace(/대견갑/g,'대견갑')};
    INV.bag.forEach(_fixShieldName);
    for(const s of SLOT_NAMES)_fixShieldName(INV.equipped[s]);
    // 삭제된 석궁 타입 마이그레이션 (중석궁/공성석궁 → 석궁)
    const _fixBow=(it)=>{if(it&&it.btype&&!BOWTYPES[it.btype]){it.btype='crossbow';it.name='석궁';it.emoji='⚙️'}};
    INV.bag.forEach(_fixBow);
    for(const s of SLOT_NAMES)_fixBow(INV.equipped[s]);
    // 구버전 아이템 affixes/implicit/legendary 마이그레이션
    const _fixItem=(it)=>{
      if(!it)return;
      if(!it.affixes)it.affixes=[];
      // 구버전 prefix/suffix 단일 객체 → affixes 배열로 이식
      if(it.prefix&&typeof it.prefix==='object'&&it.prefix.name&&!it.affixes.length){
        it.affixes.push({id:'legacy',tier:0,value:it.prefix.val||0});
      }
      if(it.suffix&&typeof it.suffix==='object'&&it.suffix.name&&!it.affixes.find(function(a){return a.id==='legacySuf'})){
        it.affixes.push({id:'legacySuf',tier:0,value:it.suffix.val||0});
      }
    };
    INV.bag.forEach(_fixItem);
    for(const s of SLOT_NAMES)_fixItem(INV.equipped[s]);
    // 근접무기 공속 마이그레이션: spdMul→0.45 반영 (spd 재계산)
    const _fixWpnSpd=(it)=>{if(it&&it.slot==='weapon'&&it.wtype&&(it._spdMig||0)<3){
      const rm=RARITY_MUL[it.rarity||0]||1;
      it.spd=+(0.45*rm).toFixed(2);
      it._spdMig=3}};
    INV.bag.forEach(_fixWpnSpd);
    for(const s of SLOT_NAMES)_fixWpnSpd(INV.equipped[s]);
    // 무기 표시명 마이그레이션: 구 wpNames(타입 무관 '대검') 저장분을 _weaponName(타입별 정합)으로 재생성.
    //   name(표시 문자열)만 갱신 — wtype/id/스탯 불변 → 세이브 타입 identity 유지.
    const _fixWpnName=(it)=>{if(it&&typeof it.uniqueId==='string'&&it.uniqueId.length>0)return;if(it&&it.slot==='weapon'&&it.wtype&&WTYPES[it.wtype]&&(it._nameMig||0)<1){
      it.name=_weaponName(it.wtype,it.el||0,it.tier||0);
      it._nameMig=1}};
    INV.bag.forEach(_fixWpnName);
    for(const s of SLOT_NAMES)_fixWpnName(INV.equipped[s]);
  }
  INV.selected=null;
  // Stats
  if(d.stats)for(const k in d.stats)STATS[k]=d.stats[k]||0;
  // Passives (known keys only)
  if(d.passives)for(const k in d.passives)if(PASSIVES.hasOwnProperty(k))PASSIVES[k]=d.passives[k]||0;
  // removed passive migration: pShield(수호) -> AP refund
  {
    const _legacyLv=Math.max(0,~~(PASSIVES.pShield||0));
    if(_legacyLv>0){
      const _pcv=[1,1,1,2,2,2,3,3,3,5];
      let _refundAP=0;
      for(let _i=0;_i<_legacyLv;_i++)_refundAP+=(_pcv[_i]||5);
      P.ap=(P.ap||0)+_refundAP;
      PASSIVES.pShield=0;
    }
  }
  // removed passive migration: pDef(철벽) -> AP refund
  {
    const _legacyLv=Math.max(0,~~((d.passives&&d.passives.pDef)||0));
    if(_legacyLv>0){
      const _pcv=[1,1,1,2,2,2,3,3,3,5];
      let _refundAP=0;
      for(let _i=0;_i<_legacyLv;_i++)_refundAP+=(_pcv[_i]||5);
      P.ap=(P.ap||0)+_refundAP;
    }
  }
  // migrate skills.humanity/demonRevive → PASSIVES.pHuman/pDemon
  if(d.skills){
    if(d.skills.humanity>0&&!PASSIVES.pHuman){PASSIVES.pHuman=Math.min(10,d.skills.humanity);delete d.skills.humanity}
    if(d.skills.demonRevive>0&&!PASSIVES.pDemon){PASSIVES.pDemon=Math.min(10,d.skills.demonRevive);delete d.skills.demonRevive}
  }
  _grit=d.grit||0;
  if(_grit>0&&!d.gritCostModeV2){const _legacySpent=_grit*3+((_grit-1)*_grit)/2;const _refund=Math.max(0,_legacySpent-_grit);if(_refund>0)P.sp+=_refund;}
  // Quickslots (filter out removed potions)
  if(d.qslots){
    QSLOTS=d.qslots.map(s => (s.type && !POT[s.type]) ? {type:null,count:0} : s);
  }
  // Game state
  if(d.game){
    G.stage=d.game.stage||0;
    G.kills=d.game.kills||0;
    // 악의(mats)도 계정 공유: 세이브 잔여분은 "합산"이 아닌 "최댓값 동기화"만 수행
    // 재접속 시 같은 세이브 잔여 악의를 반복 합산해 폭증하던 회귀 방지
    const _savedMats=Math.max(0,Math.floor(+d.game.mats||0));
    const _sharedMats=_loadSharedMats();
    if(_savedMats>0&&_savedMats!==_sharedMats){_saveSharedMats(Math.max(_sharedMats,_savedMats));d.game.mats=0}
    G.mats=Math.max(0,_loadSharedMats());
    G._irisSz=d.game.irisSz||20;
    G._taRecords=d.game.taRecords||{};G._clearRecords=d.game.clearRecords||{};G.comboMax=d.game.comboMax||0;G.playTime=d.game.playTime||0; // [CLEAR-RESULT] 구세이브 결측=기록없음
    G._cutsceneDone=d.game.cutsceneDone||false;
  }
  // Bag
  BAG_MAX=d.bagMax||300;
  // Hell cleared
  G.hellCleared=d.hellCleared||[];
  // Storage: 창고는 localStorage 공유 — 세이브 파일의 storage는 완전 무시
  // 레거시 이관: 세이브에 storage[0]이 남아있고, localStorage에는 아직 없을 때만 1회 이관
  // (이미 sharedStorage가 있으면 그게 정본이므로 세이브 데이터는 버린다)
  if(d.storage&&d.storage[0]&&d.storage[0].length>0){
