  // 안전장치: 200개 초과 시 잘라냄
  if(STORAGE[0]&&STORAGE[0].length>STORAGE_MAX){STORAGE[0].length=STORAGE_MAX;_persistSharedStorage()}
  // 결정 주머니 복원 + 마이그레이션
  CRYSTAL_BAG=d.crystalBag||[];CRYSTAL_DUST=d.crystalDust||0;
  const _fixCr=it=>{if(!it)return;if(it.socketCount===undefined){const _r=Math.random();it.socketCount=_r<.5?1:_r<.8?2:_r<.95?3:4;it.crystals=new Array(it.socketCount).fill(null)}};
  if(INV.bag)INV.bag.forEach(_fixCr);for(const s of SLOT_NAMES)_fixCr(INV.equipped[s]);
  if(STORAGE)for(const k in STORAGE){const st=STORAGE[k];if(Array.isArray(st))st.forEach(_fixCr)}
  // Upgrades
  if(d.upgrades)UPGRADES=d.upgrades;
  if(d.potLv)for(const k in d.potLv){if(POT[k]!==undefined)POT_LV[k]=d.potLv[k];}
  // Skills
  if(d.skills){
    const _knownSkillIds=new Set(SKILL_LIST.map(sk=>sk.id));
    for(const k in d.skills)if(_knownSkillIds.has(k))P.skills[k]=d.skills[k];
    // 마이그레이션: 옛 chargeStock/chargeRange → chargeBoost 통합
    if(d.skills.chargeStock||d.skills.chargeRange){
      const oldRange=d.skills.chargeRange||0;
      P.skills.chargeBoost=Math.max(1,oldRange);
    }
  }
  // 합체 상태 복원 (수동 합체: 드래그로만 합체 가능, 자동 합체 없음)
  if(d.fused){P._fused=d.fused}
  else{P._fused={}}
  P._skProf=d.skProf||{};
  P._fuseProfSec=d.fuseProfSec||{};
  P._cardProf=d.cardProf||{};
  P._catProf=d.catProf||{};
  // 로드 시 숙련도는 세이브 값 그대로 (부스트 제거)
  // 로드 시 상한 초과 클램프
  for(const _sk in P._skProf){const _c=_skProfCap(_sk);if(P._skProf[_sk]>_c)P._skProf[_sk]=_c;}
  // 마이그레이션: 기검참 기본 보유
  if(!P.skills.kiSlash)P.skills.kiSlash=1;
  if(!P.activeLMBSk||P.activeLMBSk==='whirlwind'&&!P.skills.whirlwind)P.activeLMBSk='kiSlash';
  // 회전기폭 계열 합체 상태면 LMB 자동 회전참 전환
  if(P._fused&&(P._fused.whirlDet||P._fused.slamStorm||P._fused.stormBeam)&&P.skills.whirlwind>=1)P.activeLMBSk='whirlwind';
  // 구세이브 마이그레이션: dimHalf 제거 (galeSlash 삭제됨)
  if(P._fused.dimHalf)delete P._fused.dimHalf;
  if(P.skills.galeSlash){delete P.skills.galeSlash;}
  if(P.activeChargeSk==='galeSlash')P.activeChargeSk='charge';
  // elemFuse 있는데 sixFuse 없으면 둘 다 세팅
  if(P._fused.elemFuse&&!P._fused.sixFuse)P._fused.sixFuse=true;
  // slamStorm 있는데 whirlDet 없으면 둘 다 세팅
  if(P._fused.slamStorm&&!P._fused.whirlDet)P._fused.whirlDet=true;
  // stormBurst 있으면 stormBeam+하위 전부 보장
  if(P._fused.stormBurst){if(!P._fused.stormBeam)P._fused.stormBeam=true;if(!P.skills.burstLoop)P.skills.burstLoop=1;}
  // stormBeam 있으면 slamStorm+elemFuse+하위 전부 보장
  if(P._fused.stormBeam){if(!P._fused.slamStorm)P._fused.slamStorm=true;if(!P._fused.whirlDet)P._fused.whirlDet=true;if(!P._fused.elemFuse)P._fused.elemFuse=true;if(!P._fused.sixFuse)P._fused.sixFuse=true;if(!P.skills.whirlwind)P.skills.whirlwind=1;if(!P.skills.detonate)P.skills.detonate=1;if(!P.skills.giantSlam)P.skills.giantSlam=1;if(!P.skills.fanShot)P.skills.fanShot=1;if(!P.skills.omniBeam)P.skills.omniBeam=1;if(!P.skills.elemMissile)P.skills.elemMissile=1;if(!P.skills.peaceShield)P.skills.peaceShield=1;if(!P.skills.hellRay)P.skills.hellRay=1;}

  // Lv300 히든: 푸른비 자동 해금
  if(P.lv>=300&&!P.skills.blueShot)P.skills.blueShot=1;
  // Lv700 히든: 버스트루프 자동 해금 (좌클릭)
  if(P.lv>=700&&!P.skills.burstLoop)P.skills.burstLoop=1;
  // elecRepent 있으면 boneStorm 하위 보장
  if(P._fused.elecRepent){if(!P._fused.boneStorm)P._fused.boneStorm=true;if(!P.skills.boneWall)P.skills.boneWall=1;if(!P.skills.hellRay)P.skills.hellRay=1}
  // holyIce 있으면 holyFuse 하위 보장
  if(P._fused.holyIce){if(!P._fused.holyFuse)P._fused.holyFuse=true;if(!P.skills.iceStorm)P.skills.iceStorm=1}
  // 신성빙결→약화영역 체인 보장
  if(P._fused.holyWeak1){if(!P._fused.holyIce)P._fused.holyIce=true;if(!P.skills.weakPhys)P.skills.weakPhys=1}
  if(P._fused.holyWeak2){if(!P._fused.holyWeak1)P._fused.holyWeak1=true;if(!P.skills.weakMag)P.skills.weakMag=1}
  if(P._fused.holyWeak3){if(!P._fused.holyWeak2)P._fused.holyWeak2=true;if(!P.skills.weakPj)P.skills.weakPj=1}
  if(P._fused.holyWeak4){if(!P._fused.holyWeak3)P._fused.holyWeak3=true;if(!P.skills.weakRev)P.skills.weakRev=1}
  // 구버전 마이그레이션 (제거된 키 정리)
  delete P._fused.holyFlame;delete P._fused.holyRevive;delete P._fused.holyApex;
  delete P._fused.weakFuse2;delete P._fused.weakFuse3;delete P._fused.weakFuse4;
  // dimBlast/dimRush/dimThunder/dimSlam 체인 보장
  if(P._fused.dimBlast&&!P._fused.dimRush)P._fused.dimRush=true;
  if(P._fused.dimRush&&!P._fused.dimThunder)P._fused.dimThunder=true;
  if(P._fused.dimThunder&&!P._fused.dimSlam)P._fused.dimSlam=true;
  if(P._fused.dimSlam&&!P._fused.dimBreach)P._fused.dimBreach=true;
  // 합체 구성 스킬 습득 보장: 합체 상태인데 레벨 0인 스킬 자동 보정
  for(const[_fk,_fv]of Object.entries(_FUSE_PAIRS||{})){
    if(P._fused&&P._fused[_fk]){for(const _sid of _fv){if(!P.skills[_sid])P.skills[_sid]=1}}
  }
  // min-level 강제 전면 제거 — 하위 합체가 상위 스킬을 끌어내리는 버그 방지
  // 합체 레벨 동기화는 스킬 패널(_skClick)에서만 처리
  // 스킬 슬롯 복원
  if(d.activeChargeSk)P.activeChargeSk=d.activeChargeSk;
  // 진동보행 삭제됨 — 마이그레이션
  if(P.activeChargeSk==='quakeStride')P.activeChargeSk='charge';
  // 유효성: 세팅된 스킬이 미습득이면 기본 돌진으로
  if(P.activeChargeSk!=='charge'&&!(P.skills[P.activeChargeSk]>=1))P.activeChargeSk='charge';
  // 활 스킬 슬롯 복원 (T자동)
  if(d.activeBowSk)P.activeBowSk=d.activeBowSk;
  if(!P.activeBowSk)P.activeBowSk='normal';
  if(P.activeBowSk==='maliceMortar'||P.activeBowSk==='ghostXbowTurret')P.activeBowSk='normal'; // 마이그레이션
  if(P.activeBowSk!=='normal'&&!(P.skills[P.activeBowSk]>=1))P.activeBowSk='normal';
  if(P.activeBowSk==='fanShot'&&(_isFused('sixFuse')||_isFused('elemFuse')||_isFused('stormBeam')))P.activeBowSk='normal';
  // 기본 스킬 습득 마이그레이션
  if(!P.skills.spikeTrap)P.skills.spikeTrap=1;
  if(!P.skills.holyDome){P.skills.holyDome=1}
  if(!P.skills.giantSlam){P.skills.giantSlam=1}
  // holyDome/giantSlam 슬롯 강제 고정은 슬롯 복원 후 실행 (아래)
  // 기술 스킬 슬롯 복원 (Space)
  if(d.activeTechSk)P.activeTechSk=d.activeTechSk;
  if(!P.activeTechSk||P.activeTechSk==='spikeTrap')P.activeTechSk='giantSlam';
  if(P.activeTechSk!=='giantSlam'&&!(P.skills[P.activeTechSk]>=1))P.activeTechSk='giantSlam';
  // 마법 스킬 슬롯 복원 (스킬 소유 OR 슬롯 등록 스킬이면 유효)
  if(d.activeMagicSk)P.activeMagicSk=d.activeMagicSk;
  if(!P.activeMagicSk||P.activeMagicSk==='fanShot')P.activeMagicSk='fireball';
  {const _msDef=typeof SKILL_SLOT_DEFS!=='undefined'&&SKILL_SLOT_DEFS.magic;
  const _msValid=P.activeMagicSk==='fireball'||(P.skills[P.activeMagicSk]>=1)||(_msDef&&_msDef.skills.includes(P.activeMagicSk));
  if(!_msValid)P.activeMagicSk='fireball'}
  // LMB/RMB/Q 슬롯 복원
