  if(!P.activeLMBSk)P.activeLMBSk='whirlwind';
  // 회전기폭 계열 합체 시 LMB 강제 회전참 (세이브 값 덮어쓰기 후 재적용)
  if(P._fused&&(P._fused.whirlDet||P._fused.slamStorm||P._fused.stormBeam)&&P.skills.whirlwind>=1)P.activeLMBSk='whirlwind';
  if(d.activeRMBSk)P.activeRMBSk=d.activeRMBSk;
  if(!P.activeRMBSk)P.activeRMBSk='shieldBlock';
  if(d.activeQSk)P.activeQSk=d.activeQSk;
  if(!P.activeQSk||P.activeQSk==='iceOrb')P.activeQSk='parry'; // 얼음보주→선택스킬 마이그레이션
  if(d.activeCtSk)P.activeCtSk=d.activeCtSk;
