  if(!P||_saving)return;
  _saving=true;
  try{_saveSharedMats(G.mats||0);_flushSharedStorage()}catch(e){}
  try{
    const saveData={
      ts:Date.now(),
      player:{lv:P.lv,exp:P.exp,maxExp:P.maxExp,sp:P.sp,ap:P.ap||0,
        transLvDate:P._transLvDate||null,transLvCount:P._transLvCount||0,apBossCleared:P._apBossCleared||[],goddessGift:P._goddessGift||[],
        baseAtk:P.baseAtk,baseDef:P.baseDef,mpR:P.mpR,stR:P.stR,
        hp:P.hp,mhp:P.mhp,mp:P.mp,mmp:P.mmp,st:P.st,mst:P.mst,speed:P.speed,
        shield:P.shield,mshield:P.mshield,maskOn:P.maskOn},
      inv:{bag:INV.bag,equipped:INV.equipped,ossCollect:INV.ossCollect||{}},
      stats:{...STATS},passives:{...PASSIVES},grit:_grit,gritCostModeV2:1,
      qslots:QSLOTS,
      game:{stage:G.stage,kills:G.kills,mats:0,irisSz:G._irisSz||20,taRecords:G._taRecords||{},clearRecords:G._clearRecords||{},comboMax:G.comboMax||0,playTime:G.playTime||0,cutsceneDone:G._cutsceneDone||false},
      bagMax:BAG_MAX,hellCleared:G.hellCleared||[],storage:{},
      crystalBag:CRYSTAL_BAG,crystalDust:CRYSTAL_DUST,
      upgrades:{...UPGRADES},potLv:{...POT_LV},skills:{...P.skills},
      fused:P._fused||{},skProf:P._skProf||{},fuseProfSec:P._fuseProfSec||{},cardProf:P._cardProf||{},catProf:P._catProf||{},
      activeChargeSk:P.activeChargeSk||'charge',
      activeBowSk:P.activeBowSk||'normal',
      activeTechSk:P.activeTechSk||'giantSlam',
      activeMagicSk:P.activeMagicSk||'fireball',
      activeLMBSk:P.activeLMBSk||'whirlwind',
      activeRMBSk:P.activeRMBSk||'shieldBlock',
      activeQSk:P.activeQSk||'parry',
      activeCtSk:P.activeCtSk||'ghostWalk',
      skillSlots:SKILL_SLOTS,
      ultSlot:ULT_SLOT,
      charIdx:_charIdx
    };
    if(_serverOk===false){localStorage.setItem('hellsave_'+_SLOT,JSON.stringify(saveData));_lastSaveTime=Date.now();return}
    const res=await fetch('/api/save',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({slot:_SLOT,data:saveData})});
    if(!res.ok){_serverOk=false;try{localStorage.setItem('hellsave_'+_SLOT,JSON.stringify(saveData));_lastSaveTime=Date.now()}catch(le){}return}
    _serverOk=true;
    const j=await res.json();
    if(j.ok){_lastSaveTime=Date.now()}
    else{if(!IS_ELECTRON)console.error('[LOCAL] Save failed:',j.error)}
  }catch(e){_serverOk=false;try{localStorage.setItem('hellsave_'+_SLOT,JSON.stringify(saveData));_lastSaveTime=Date.now()}catch(le){}}
  finally{_saving=false;if(_pendingForce){_pendingForce=false;if(Date.now()-_lastSaveTime>=5000)dbSave()}}
};

